-- SOEN363 Phase 1 - COMPLETELY FICTIONAL synthetic hospital dataset.
-- All names, addresses, telephone numbers, insurance numbers, and medical encounters are invented.
-- For education and database testing only; no real patient information.
-- PostgreSQL 17. Run schema.sql, then constraints.sql, then this file.
-- Run once on empty tables. Explicit identity values are inserted with OVERRIDING SYSTEM VALUE.
BEGIN;

-- Patients (28 records)

-- Admissions (40 records)

-- ICD9Dictionary (24 records)

-- Diagnosis (64 records)

-- TriageAssessments (40 records)

-- ClinicalNotes (107 records)

-- UnitStays (87 records)

-- DiagnosticOrders (70 records)

-- DiagnosticExaminations (40 records)

-- RadiologyExaminations (30 records)

-- RadiologyReports (30 records)

-- SurgicalProcedures (8 records)

-- DischargeRecords (39 records)

SELECT setval(pg_get_serial_sequence('public.patients', 'patient_id'), (SELECT MAX(patient_id) FROM Patients));
SELECT setval(pg_get_serial_sequence('public.admissions', 'admission_id'), (SELECT MAX(admission_id) FROM Admissions));
SELECT setval(pg_get_serial_sequence('public.diagnosis', 'diagnosis_id'), (SELECT MAX(diagnosis_id) FROM Diagnosis));
SELECT setval(pg_get_serial_sequence('public.triageassessments', 'triage_id'), (SELECT MAX(triage_id) FROM TriageAssessments));
SELECT setval(pg_get_serial_sequence('public.clinicalnotes', 'note_id'), (SELECT MAX(note_id) FROM ClinicalNotes));
SELECT setval(pg_get_serial_sequence('public.unitstays', 'unit_stay_id'), (SELECT MAX(unit_stay_id) FROM UnitStays));
SELECT setval(pg_get_serial_sequence('public.diagnosticorders', 'order_id'), (SELECT MAX(order_id) FROM DiagnosticOrders));
SELECT setval(pg_get_serial_sequence('public.diagnosticexaminations', 'exam_id'), (SELECT MAX(exam_id) FROM DiagnosticExaminations));
SELECT setval(pg_get_serial_sequence('public.radiologyexaminations', 'radiology_exam_id'), (SELECT MAX(radiology_exam_id) FROM RadiologyExaminations));
SELECT setval(pg_get_serial_sequence('public.radiologyreports', 'report_id'), (SELECT MAX(report_id) FROM RadiologyReports));
SELECT setval(pg_get_serial_sequence('public.surgicalprocedures', 'procedure_id'), (SELECT MAX(procedure_id) FROM SurgicalProcedures));
SELECT setval(pg_get_serial_sequence('public.dischargerecords', 'discharge_id'), (SELECT MAX(discharge_id) FROM DischargeRecords));

COMMIT;
